fun linearizable(all: List<Op>): Boolean {
    val placed = BitSet(all.size)
    val seen = HashSet<Pair<BitSet, Int?>>()
    fun go(count: Int, state: Int?): Boolean {
        if (count == all.size) return true
        if (!seen.add((placed.clone() as BitSet) to state)) return false
        val minEnd = all.indices.filter { !placed[it] }.minOf { all[it].end }
        for (i in all.indices) {
            if (placed[i]) continue
            if (all[i].start > minEnd) break               // not minimal, nor anything after it
            val (ok, next) = Register.step(state, all[i])
            if (!ok) continue
            placed.set(i)
            if (go(count + 1, next)) return true
            placed.clear(i)                                 // dead end: take it back
        }
        return false
    }
    return go(0, null)
}
